'use server'

import { createClient } from '@/lib/supabase/server'
import { revalidatePath } from 'next/cache'
import { redirect } from 'next/navigation'

export async function createProduct(formData: FormData) {
  const supabase = await createClient()

  const nombre = formData.get('nombre') as string
  const descripcion = formData.get('descripcion') as string
  const precio = parseFloat(formData.get('precio') as string)
  const imageFile = formData.get('imagen') as File
  const pdfFile = formData.get('archivo') as File

  let imagen_url = ''
  let archivo_url = ''

  // 1. Subir Imagen
  if (imageFile && imageFile.size > 0) {
    const fileExt = imageFile.name.split('.').pop()
    const fileName = `${Math.random()}.${fileExt}`
    const { data: uploadData, error: uploadError } = await supabase.storage
      .from('productos-portadas')
      .upload(fileName, imageFile)

    if (uploadError) {
      console.error('Error subiendo imagen:', uploadError)
    } else {
      const { data: { publicUrl } } = supabase.storage
        .from('productos-portadas')
        .getPublicUrl(fileName)
      imagen_url = publicUrl
    }
  }

  // 2. Subir Archivo PDF
  if (pdfFile && pdfFile.size > 0) {
    const fileExt = pdfFile.name.split('.').pop()
    const fileName = `${Math.random()}.${fileExt}`
    const { data: uploadData, error: uploadError } = await supabase.storage
      .from('productos-archivos')
      .upload(fileName, pdfFile)

    if (uploadError) {
      console.error('Error subiendo PDF:', uploadError)
    } else {
      const { data: { publicUrl } } = supabase.storage
        .from('productos-archivos')
        .getPublicUrl(fileName)
      archivo_url = publicUrl
    }
  }

  // 3. Insertar en DB
  const { error } = await supabase
    .from('productos')
    .insert({
      nombre,
      descripcion,
      precio,
      imagen_url,
      archivo_url,
    })

  if (error) {
    console.error('Error insertando producto:', error)
    // Redirigir con error si es necesario
    return
  }

  revalidatePath('/commerce/admin')
  revalidatePath('/commerce/shop')
  redirect('/commerce/admin')
}
